def _generated_cases():
    for exemplar, category in CATEGORY_EXEMPLARS:
        for prefix in TEST_PREFIXES:
            for ext in CERT_EXTENSIONS:
                yield f"{prefix}{exemplar}{ext}", category

@pytest.mark.parametrize("directory", SECRET_DIRS)
